#!/bin/bash
set -e
cd avbox

echo "=== 写入洛雪音乐脚本引擎 ==="

# 1. 写入 LxScriptEngine.kt
mkdir -p app/src/main/java/com/github/tvbox/osc/util
echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/util/LxScriptEngine.kt
echo "LxScriptEngine.kt 已写入"

# 2. 写入 LxSourceManager.kt
echo "" | base64 -d > app/src/main/java/com/github/tvbox/osc/util/LxSourceManager.kt
echo "LxSourceManager.kt 已写入"

# 3. 写入 preload.js 到 assets
mkdir -p app/src/main/assets/lx
echo "" | base64 -d > app/src/main/assets/lx/preload.js
echo "preload.js 已写入"

echo "=== 音乐脚本引擎写入完成 ==="
ls -lh app/src/main/java/com/github/tvbox/osc/util/Lx*.kt
ls -lh app/src/main/assets/lx/